<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Snake</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    background: #0d0d0d;
    color: #e0e0e0;
    font-family: 'Courier New', monospace;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-height: 100vh;
    gap: 18px;
  }
  h1 {
    font-size: 2rem;
    letter-spacing: 0.2em;
    color: #4eff91;
    text-shadow: 0 0 12px #4eff9188;
  }
  #score-wrap {
    font-size: 1.2rem;
    color: #aaa;
    letter-spacing: 0.1em;
  }
  #score {
    color: #4eff91;
    font-weight: bold;
    font-size: 1.4rem;
  }
  #snake {
    display: block;
    border: 2px solid #2a2a2a;
    border-radius: 4px;
    background: #111;
    box-shadow: 0 0 30px #0008;
  }
  .controls {
    display: flex;
    gap: 12px;
  }
  button {
    padding: 10px 28px;
    font-size: 1rem;
    font-family: 'Courier New', monospace;
    border: 2px solid #333;
    border-radius: 4px;
    background: #1a1a1a;
    color: #ccc;
    cursor: pointer;
    letter-spacing: 0.05em;
    transition: background 0.15s, border-color 0.15s, color 0.15s;
  }
  button:hover { background: #252525; border-color: #4eff91; color: #4eff91; }
  #start  { border-color: #4eff91; color: #4eff91; }
  #pause  { border-color: #ffe04e; color: #ffe04e; }
  #reset  { border-color: #ff5555; color: #ff5555; }
  #start:hover  { background: #0d2018; }
  #pause:hover  { background: #201e0d; }
  #reset:hover  { background: #200d0d; }
  #message {
    font-size: 1rem;
    color: #ff5555;
    min-height: 1.4em;
    letter-spacing: 0.05em;
  }
</style>
</head>
<body>
<h1>SNAKE</h1>
<div id="score-wrap">SCORE: <span id="score">0</span></div>
<canvas id="snake" width="420" height="420"></canvas>
<div class="controls">
  <button id="start">START</button>
  <button id="pause">PAUSE</button>
  <button id="reset">RESET</button>
</div>
<div id="message"></div>

<script>
(function() {
  const canvas = document.getElementById('snake');
  const ctx = canvas.getContext('2d');
  const scoreEl = document.getElementById('score');
  const msgEl = document.getElementById('message');

  const COLS = 21;
  const ROWS = 21;
  const CELL = Math.floor(canvas.width / COLS);

  // Effective canvas size based on cell size
  const CW = COLS * CELL;
  const CH = ROWS * CELL;

  let snakeBody, dir, nextDir, foodPos, _score, _alive;
  let loopId = null;
  let paused = false;
  const TICK_MS = 120;

  function initState() {
    const midX = Math.floor(COLS / 2);
    const midY = Math.floor(ROWS / 2);
    snakeBody = [
      [midX, midY],
      [midX - 1, midY],
      [midX - 2, midY],
    ];
    dir = 'right';
    nextDir = 'right';
    _score = 0;
    _alive = true;
    placeFood();
    scoreEl.textContent = '0';
    msgEl.textContent = '';
  }

  function placeFood() {
    const free = [];
    const occupied = new Set(snakeBody.map(([x, y]) => `${x},${y}`));
    for (let x = 0; x < COLS; x++) {
      for (let y = 0; y < ROWS; y++) {
        if (!occupied.has(`${x},${y}`)) free.push([x, y]);
      }
    }
    if (free.length === 0) return;
    foodPos = free[Math.floor(Math.random() * free.length)];
  }

  function step() {
    if (!_alive) return;

    dir = nextDir;
    const [hx, hy] = snakeBody[0];
    let nx = hx, ny = hy;
    if (dir === 'up')    ny--;
    if (dir === 'down')  ny++;
    if (dir === 'left')  nx--;
    if (dir === 'right') nx++;

    // Wall collision
    if (nx < 0 || nx >= COLS || ny < 0 || ny >= ROWS) {
      _alive = false;
      draw();
      msgEl.textContent = 'GAME OVER — hit a wall';
      stopLoop();
      return;
    }

    // Self collision (exclude tail tip which will move away, unless eating)
    const eating = (nx === foodPos[0] && ny === foodPos[1]);
    const checkBody = eating ? snakeBody : snakeBody.slice(0, -1);
    for (const [bx, by] of checkBody) {
      if (nx === bx && ny === by) {
        _alive = false;
        draw();
        msgEl.textContent = 'GAME OVER — hit yourself';
        stopLoop();
        return;
      }
    }

    snakeBody.unshift([nx, ny]);
    if (eating) {
      _score++;
      scoreEl.textContent = _score;
      placeFood();
    } else {
      snakeBody.pop();
    }
    draw();
  }

  // Colors
  const COLOR_HEAD    = '#4eff91';
  const COLOR_BODY    = '#27a85a';
  const COLOR_OUTLINE = '#0d3320';
  const COLOR_FOOD    = '#ff4e4e';
  const COLOR_FOOD_GLOW = '#ff4e4e44';
  const COLOR_GRID    = '#161616';
  const COLOR_DEAD    = '#555';

  function draw() {
    // Background
    ctx.fillStyle = '#111';
    ctx.fillRect(0, 0, CW, CH);

    // Grid
    ctx.strokeStyle = COLOR_GRID;
    ctx.lineWidth = 0.5;
    for (let x = 0; x <= COLS; x++) {
      ctx.beginPath();
      ctx.moveTo(x * CELL, 0);
      ctx.lineTo(x * CELL, CH);
      ctx.stroke();
    }
    for (let y = 0; y <= ROWS; y++) {
      ctx.beginPath();
      ctx.moveTo(0, y * CELL);
      ctx.lineTo(CW, y * CELL);
      ctx.stroke();
    }

    // Food
    const [fx, fy] = foodPos;
    const fcx = fx * CELL + CELL / 2;
    const fcy = fy * CELL + CELL / 2;
    const fr = CELL * 0.35;
    const grd = ctx.createRadialGradient(fcx, fcy, 1, fcx, fcy, fr * 1.5);
    grd.addColorStop(0, '#ff8080');
    grd.addColorStop(1, COLOR_FOOD);
    ctx.fillStyle = grd;
    ctx.beginPath();
    ctx.arc(fcx, fcy, fr, 0, Math.PI * 2);
    ctx.fill();

    // Snake
    const dead = !_alive;
    snakeBody.forEach(([x, y], i) => {
      const px = x * CELL + 1;
      const py = y * CELL + 1;
      const sz = CELL - 2;
      const r = Math.max(2, sz * 0.3);

      if (i === 0) {
        ctx.fillStyle = dead ? COLOR_DEAD : COLOR_HEAD;
      } else {
        const t = i / snakeBody.length;
        if (dead) {
          ctx.fillStyle = '#444';
        } else {
          const g = Math.floor(0x27 + (0x4e - 0x27) * (1 - t));
          ctx.fillStyle = `rgb(0, ${g}, ${Math.floor(g * 0.45)})`;
        }
      }

      ctx.beginPath();
      ctx.roundRect(px, py, sz, sz, r);
      ctx.fill();

      // Outline
      ctx.strokeStyle = dead ? '#333' : COLOR_OUTLINE;
      ctx.lineWidth = 1;
      ctx.stroke();

      // Eyes on head
      if (i === 0 && _alive) {
        ctx.fillStyle = '#fff';
        const ex = x * CELL + CELL / 2;
        const ey = y * CELL + CELL / 2;
        const eo = CELL * 0.18;
        const er = CELL * 0.07;

        let e1x = ex, e1y = ey, e2x = ex, e2y = ey;
        if (dir === 'right') { e1x += eo * 0.5; e1y -= eo; e2x += eo * 0.5; e2y += eo; }
        if (dir === 'left')  { e1x -= eo * 0.5; e1y -= eo; e2x -= eo * 0.5; e2y += eo; }
        if (dir === 'up')    { e1x -= eo; e1y -= eo * 0.5; e2x += eo; e2y -= eo * 0.5; }
        if (dir === 'down')  { e1x -= eo; e1y += eo * 0.5; e2x += eo; e2y += eo * 0.5; }

        ctx.beginPath(); ctx.arc(e1x, e1y, er, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(e2x, e2y, er, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = '#111';
        ctx.beginPath(); ctx.arc(e1x + 0.5, e1y + 0.5, er * 0.5, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(e2x + 0.5, e2y + 0.5, er * 0.5, 0, Math.PI * 2); ctx.fill();
      }
    });
  }

  function startLoop() {
    if (loopId) return;
    if (!_alive) return;
    paused = false;
    loopId = setInterval(() => {
      if (!paused) step();
    }, TICK_MS);
  }

  function stopLoop() {
    if (loopId) { clearInterval(loopId); loopId = null; }
  }

  // Buttons
  document.getElementById('start').addEventListener('click', () => {
    if (!_alive) { initState(); draw(); }
    paused = false;
    msgEl.textContent = '';
    startLoop();
  });

  document.getElementById('pause').addEventListener('click', () => {
    if (!_alive) return;
    paused = !paused;
    if (paused) {
      msgEl.textContent = 'PAUSED';
      stopLoop();
    } else {
      msgEl.textContent = '';
      startLoop();
    }
  });

  document.getElementById('reset').addEventListener('click', () => {
    stopLoop();
    paused = false;
    initState();
    draw();
  });

  // Keyboard
  const KEY_DIR = {
    ArrowUp: 'up', ArrowDown: 'down', ArrowLeft: 'left', ArrowRight: 'right',
    w: 'up', s: 'down', a: 'left', d: 'right',
  };
  document.addEventListener('keydown', e => {
    const d = KEY_DIR[e.key];
    if (d) {
      e.preventDefault();
      window.game.setDir(d);
    }
    if (e.key === ' ') {
      e.preventDefault();
      if (!_alive) {
        document.getElementById('start').click();
      } else {
        document.getElementById('pause').click();
      }
    }
  });

  // Public API
  window.game = {
    get w() { return COLS; },
    get h() { return ROWS; },

    reset() {
      stopLoop();
      paused = false;
      initState();
      draw();
    },

    tick() {
      step();
    },

    setDir(d) {
      const opposite = { up: 'down', down: 'up', left: 'right', right: 'left' };
      if (opposite[dir] === d) return; // ignore 180°
      if (['up','down','left','right'].includes(d)) nextDir = d;
    },

    setFood(x, y) {
      foodPos = [x, y];
      draw();
    },

    snake() { return snakeBody.map(([x, y]) => [x, y]); },
    food()  { return [foodPos[0], foodPos[1]]; },
    alive() { return _alive; },
    score() { return _score; },
  };

  // Init
  initState();
  draw();
})();
</script>
</body>
</html>
